519	/**
520	 * Repairs the run a failed dispatch would otherwise strand in `claimed`. That
521	 * state is invisible to the claim RPC, to the poll selector and to the
522	 * terminal selector, so nothing would dial the run and nothing would retry it.
523	 *
524	 * A call this attempt placed is reconciled, never failed. The id comes from the
525	 * response when the run's own write did not land, because the phone rang and
526	 * the poll must be able to answer for it. A run with no call id fails with the
527	 * reason and a completion time. Neither path returns the run to `scheduled`,
528	 * because a second dispatch could dial the same person twice.
529	 *
530	 * The run it fails records the `finalised` row that names the reason, so the
531	 * timeline ends with a cause rather than a bare claim. A reconciliation that
532	 * hands the run to the poll records no such row, because that story continues.
533	 *
534	 * A recovery write can itself fail, and then the run keeps the state it had.
535	 * The log names the accepted call id so an operator can reconcile it by hand.
536	 * Nothing re-queues the run, because the second dial is the worse outcome.
537	 */
538	async function recoverStrandedRun(
539	  deps: CalleDeps,
540	  run: ClaimedRun,
541	  cause: unknown,
542	  placed: PlacedCall,
543	): Promise<void> {
544	  const reason = cause instanceof Error ? cause.message : "unknown error";
545	  try {
546	    const current = await readOne<{ state: string; calle_call_id: string | null }>(
547	      deps,
548	      "call_runs",
549	      new URLSearchParams({ select: "state,calle_call_id", id: `eq.${run.id}` }),
550	    );
551	    // A refusal, a 409 or a landed dispatch has already moved the run. The
552	    // recovery never overwrites a state another writer landed.
553	    if (!current || current.state !== "claimed") return;
554	    const now = deps.now();
555	    const callId = current.calle_call_id ?? placed.callId;
556	    if (callId) {
557	      await updateRun(deps, run.id, {
558	        state: "awaiting_result",
559	        calle_call_id: callId,
560	        dispatched_at: now.toISOString(),
561	        poll_after: new Date(now.getTime() + POLL_DELAY_MS).toISOString(),
562	      });
563	      return;
564	    }
565	    await updateRun(deps, run.id, {
566	      ...failedDispatchFields("dispatch_failed", reason),
567	      terminal_writer: RECOVERY_WRITER,
568	      completed_at: now.toISOString(),
569	    });
570	    await recordCallEvent(
571	      run.id,
572	      "finalised",
573	      finalisedFailureDetail("dispatch_failed", reason, "failed"),
574	      deps,
575	    );
576	  } catch (error) {
577	    console.error(
578	      `dispatch recovery failed for run ${run.id}`,
579	      error instanceof Error ? error.message : "unknown error",
580	      placed.callId
581	        ? `accepted call ${placed.callId} needs manual reconciliation`
582	        : "no call was placed",
583	    );
584	  }
585	}
